import React from 'react';
import Blobs from '../components/Blobs';
import { useMoods, useThoughts } from '../hooks/useStorage';

const TRAP_ICONS = {
  'Katastrofiering':'🌪️','Tankeläsning':'🔮','Svartvitt tänkande':'⬛',
  'Övergeneralisering':'🔁','Känslomässigt resonerande':'💭',
  'Personalisering':'🎯','Filtrerande':'🔍','Bör-tänkande':'📋',
};

const MOOD_COLORS = { 1:'#f87171',2:'#fb923c',3:'#fbbf24',4:'#34d399',5:'#60a5fa' };

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();

  const isEmpty = moods.length === 0 && thoughts.length === 0;

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 24px' }}>
        <div style={{ fontSize:56, marginBottom:20 }}>🌱</div>
        <h2 style={{ fontSize:28, fontWeight:700, color:'#fff', marginBottom:12 }}>Ingen data än</h2>
        <p style={{ fontSize:14, color:'rgba(255,255,255,0.4)', marginBottom:32 }}>
          Analysera en tanke eller gör din första incheckning för att komma igång.
        </p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={() => setPage('home')} style={{ padding:'12px 24px', borderRadius:100, background:'#fff', color:'#0e0e12', fontSize:13, fontWeight:600 }}>Analysera en tanke</button>
          <button onClick={() => setPage('checkin')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.08)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(255,255,255,0.7)', fontSize:13 }}>Daglig check-in</button>
        </div>
      </div>
    </div>
  );

  const avgEmojis = ['','😔','😟','😐','🙂','😄'];
  const maxTrap = Math.max(...Object.values(trapCounts), 1);

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs />
      <div style={{ position:'relative', zIndex:1, padding:'88px 24px 64px', maxWidth:560, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        <h1 style={{ fontSize:'clamp(36px,8vw,60px)', fontWeight:700, letterSpacing:'-0.05em', color:'#fff', marginBottom:40, lineHeight:0.9 }}>
          Din<br/><span style={{ color:'rgba(255,255,255,0.25)' }}>Historik</span>
        </h1>

        {/* Stats */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:10, marginBottom:40 }}>
          {[
            { val:`🔥 ${streak}`, label:'Dagars streak' },
            { val:thoughts.length, label:'Analyser' },
            { val: avgMood > 0 ? `${avgEmojis[Math.round(avgMood)]} ${avgMood}` : '–', label:'Snitt humör' },
          ].map(({ val, label }) => (
            <div key={label} style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, padding:'20px 16px', textAlign:'center', backdropFilter:'blur(20px)' }}>
              <div style={{ fontSize:24, fontWeight:700, color:'#fff', marginBottom:4, lineHeight:1 }}>{val}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.3)', letterSpacing:'0.12em', textTransform:'uppercase' }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Mood chart */}
        {moods.length > 0 && (
          <div style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:20, padding:'24px', backdropFilter:'blur(20px)', marginBottom:16 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', marginBottom:20 }}>Humör över tid</p>
            <div style={{ display:'flex', alignItems:'flex-end', gap:6, height:90 }}>
              {[...moods].reverse().map((m, i) => (
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:5, height:'100%', justifyContent:'flex-end' }}>
                  <span style={{ fontSize:12 }}>{m.emoji}</span>
                  <div style={{ width:'100%', borderRadius:'4px 4px 0 0', background:MOOD_COLORS[m.score], height:`${(m.score/5)*100}%`, minHeight:4 }} title={m.label} />
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(255,255,255,0.25)', whiteSpace:'nowrap' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trap frequency */}
        {Object.keys(trapCounts).length > 0 && (
          <div style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:20, padding:'24px', backdropFilter:'blur(20px)', marginBottom:16 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', marginBottom:20 }}>Vanligaste tankefällor</p>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).map(([label, count]) => (
              <div key={label} style={{ display:'flex', alignItems:'center', gap:12, marginBottom:14 }}>
                <span style={{ fontSize:12, width:20, flexShrink:0 }}>{TRAP_ICONS[label]||'💭'}</span>
                <span style={{ fontSize:12, color:'rgba(255,255,255,0.5)', flex:1, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis', fontFamily:'DM Mono,monospace' }}>{label}</span>
                <div style={{ width:80, height:4, background:'rgba(255,255,255,0.06)', borderRadius:2, flexShrink:0 }}>
                  <div style={{ height:'100%', borderRadius:2, background:'rgba(255,255,255,0.4)', width:`${(count/maxTrap)*100}%`, transition:'width .8s cubic-bezier(0.16,1,0.3,1)' }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.3)', width:20, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought entries */}
        {thoughts.length > 0 && (
          <>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', margin:'32px 0 14px' }}>Tidigare analyser</p>
            {thoughts.map(t => (
              <div key={t.id} style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, padding:'20px', backdropFilter:'blur(20px)', marginBottom:10 }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.45)', letterSpacing:'0.08em' }}>
                    {t.trap_icon||'💭'} {t.trap_label}
                  </span>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.25)' }}>
                    {new Date(t.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
                  </span>
                </div>
                <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', fontStyle:'italic', marginBottom:12, lineHeight:1.6 }}>
                  "{t.user_text.slice(0,120)}{t.user_text.length>120?'...':''}"
                </p>
                <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.12em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:6 }}>Omramning</p>
                <p style={{ fontSize:13, color:'rgba(255,255,255,0.55)', lineHeight:1.6, fontWeight:300 }}>{t.reframe}</p>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
